interface StoredReviewState {
  reviewState: AgentStoreReviewState      // @haklex/rich-agent-core 原样
  anchors: Record<string, string>         // batchId -> 产生该 batch 的 toolCallId
}

type AgentFileFrame =
  | { path: string; attach?: boolean; content: string }                  // 全文
  | { path: string; attach?: boolean; baseHash: string; patch: string }  // 补丁
  | { path: string; attach?: boolean; hash: string }                     // 未变

interface AgentRunPayload {
  runId: string
  sessionId: string
  conversationId: string | null
  model: string
  providerId: string
  user: string
  systemHash: string
  system?: string[]              // 仅在服务端未缓存时发送
  toolsHash: string
  tools?: AgentToolSchema[]      // 同上
  files: AgentFileFrame[]
}
// agent.steer: { runId, user, files: AgentFileFrame[] }
// agent.tool.result: 由 send 改为 request（需要 ack），files?: AgentFileFrame[]

// ack
{ ok: true, conversationId }                                   // run 成功
{ ok: false, code: 'CONTEXT_MISSING', missing: ('system' | 'tools')[] }
{ ok: false, code: 'FILE_BASE_MISMATCH', paths: string[] }
